<?php
declare(strict_types=1);require_once dirname(__DIR__).'/config/bootstrap.php';require_auth();$id=(int)($_GET['id']??0);$st=db()->prepare('SELECT s.*,u.full_name cashier,c.name customer_name,c.phone customer_phone,b.name branch_name,b.address branch_address,b.phone branch_phone FROM sales s INNER JOIN users u ON u.id=s.created_by INNER JOIN branches b ON b.id=s.branch_id LEFT JOIN customers c ON c.id=s.customer_id WHERE s.id=:id AND s.status IN("completed","voided")');$st->execute([':id'=>$id]);$sale=$st->fetch();if(!$sale){flash('error','Receipt not found.');redirect('sales/index.php');}$it=db()->prepare('SELECT * FROM sale_items WHERE sale_id=:id ORDER BY id');$it->execute([':id'=>$id]);$items=$it->fetchAll();$pay=db()->prepare('SELECT sp.*,pm.name method_name,pm.method_type FROM sale_payments sp INNER JOIN payment_methods pm ON pm.id=sp.payment_method_id WHERE sp.sale_id=:id ORDER BY sp.id');$pay->execute([':id'=>$id]);$payments=$pay->fetchAll();$businessName=(string)setting('business.name','Wambo wa Carpets');$pageTitle='Receipt '.$sale['sale_no'];$pageStyles=['admin.css','receipt.css'];require BASE_PATH.'/includes/header.php';require BASE_PATH.'/includes/sidebar.php';?>
<div class="app-main receipt-app-main"><?php require BASE_PATH.'/includes/navbar.php';?><main class="receipt-page"><div class="receipt-actions no-print"><a class="button button--ghost" href="<?=e(app_url('pos/index.php'))?>">New sale</a><a class="button button--secondary" href="<?=e(app_url('sales/view.php?id='.$id))?>">Sale details</a><button class="button button--primary" onclick="window.print()">Print receipt</button></div><article class="receipt-sheet"><header class="receipt-header"><div class="receipt-logo">WC</div><h1><?=e($businessName)?></h1><p><?=e($sale['branch_address']?:$sale['branch_name'])?></p><?php if($sale['branch_phone']):?><p><?=e($sale['branch_phone'])?></p><?php endif;?></header><?php if($sale['status']==='voided'):?><div class="receipt-void">VOIDED</div><?php endif;?><section class="receipt-meta"><div><span>Receipt</span><strong><?=e($sale['sale_no'])?></strong></div><div><span>Date</span><strong><?=e(format_datetime($sale['sale_date']))?></strong></div><div><span>Cashier</span><strong><?=e($sale['cashier'])?></strong></div><div><span>Customer</span><strong><?=e($sale['customer_name']?:'Walk-in customer')?></strong></div></section><table class="receipt-items"><thead><tr><th>Item</th><th>Qty</th><th>Price</th><th>Total</th></tr></thead><tbody><?php foreach($items as$i):?><tr><td><strong><?=e($i['product_name_snapshot'])?></strong><small><?=e($i['sku_snapshot'])?><?=(float)$i['discount_amount']>0?' · Disc '.e(money($i['discount_amount'])):''?></small></td><td><?=e(format_quantity($i['quantity']))?> <?=e($i['unit_snapshot'])?></td><td><?=e(money($i['unit_price']))?></td><td><?=e(money($i['line_total']))?></td></tr><?php endforeach;?></tbody></table><section class="receipt-totals"><div><span>Subtotal</span><strong><?=e(money($sale['subtotal']))?></strong></div><div><span>Discount</span><strong>-<?=e(money($sale['discount_amount']))?></strong></div><div class="receipt-grand-total"><span>Total</span><strong><?=e(money($sale['total_amount']))?></strong></div></section><section class="receipt-payments"><h3>Payment</h3><?php foreach($payments as$p):?><div><span><?=e($p['method_name'])?><?= $p['reference_no']?' · '.e($p['reference_no']):''?></span><strong><?=e(money($p['amount']))?></strong></div><?php endforeach;?><?php if((float)$sale['balance_due']>0):?><div class="receipt-balance"><span>Outstanding balance</span><strong><?=e(money($sale['balance_due']))?></strong></div><?php endif;?></section><footer class="receipt-footer"><strong>Thank you for shopping with Wambo wa Carpets.</strong><span>Receipt generated <?=e(date('d M Y H:i'))?></span></footer></article></main></div><?php require BASE_PATH.'/includes/footer.php';?>
